class Goblin:
    def __init__(self, hp):
        self.hp = hp

    def attack(self):
        return f"고블린 공격! (HP:{self.hp})"

class Troll(Goblin):
    def __init__(self, hp, size):
        super().__init__(hp)
        self.size = size

    def attack(self):
        base = super().attack()
        return base + f" [크기:{self.size}]"

t = Troll(200, "대형")
print(t.attack())
```

